/// Does `provider` support `capability`?
pub fn supports(provider: Provider, capability: Capability) -> bool {
    let value = capability;
    match provider {
        Provider::Github => matches!(value, Capability::Retarget | Capability::SquashMerge | Capability::Mergeability | Capability::NativeStacks | Capability::Checks | Capability::Pipelines | Capability::RunLogs | Capability::RequiredChecks | Capability::FastForward | Capability::Webhooks),
        Provider::Ecode => matches!(value, Capability::Retarget | Capability::SquashMerge | Capability::OrderedMerge | Capability::Mergeability | Capability::NativeStacks | Capability::RebaseOnto | Capability::Checks | Capability::Pipelines | Capability::RunLogs | Capability::RequiredChecks | Capability::FastForward | Capability::Mirror),
    }
}

impl PrState {
    /// Open or draft: the PR can still be retargeted, merged or closed.
    pub fn is_live(self) -> bool {
        let value = self;
        matches!(value, PrState::Open | PrState::Draft)
    }
}

